-- Supplier pages for Melbourne venues, the brands they carry, and maker pages
-- for those brands (after 20261017720100 adds supplier pages). Step 6e of
-- the bottle catalog plan: https://claude.ai/artifact/Vu6seuSNtN42nKYb2nDCVR
--
--   * 43 suppliers that deliver to Melbourne venues, each checked on its own
--     site: spirits, wine and beer distributors and importers (national
--     groups' Australian arms and independents), ice suppliers, fresh
--     produce and garnish wholesalers, and glassware, barware and equipment
--     suppliers. Each gets an unclaimed, public supplier page saying what it
--     supplies and the cities its own site says it serves. Business names
--     only. Leads came from the suppliers' own sites, trade press and the
--     Victorian pre-retail (wholesale) liquor licences (Liquor Control
--     Victoria, CC BY 4.0, trading names only). Seven more (Lion, the ice
--     makers, two garnish makers, a barware maker) sell their own products
--     and keep their maker pages, which say where they deliver.
--   * 343 supplier lines: whose brands each supplier carries, in Australia
--     or in one state, each with the supplier's page that says so. A brand
--     links to its maker's page: an existing page when the name matches,
--     else a brand checked on its own site.
--   * 209 new maker pages for the brands that had none, each checked on the
--     brand's own site (name, website, what it makes, and the country only
--     where a page shows it). A brand seen only on a supplier's page (a
--     possible house label), or not confirmed, gets no page and no line.
--   * Independent checks: every supplier (6 wrong facts in 282, mostly
--     fields left blank, now filled), and 60 random lines with 40 random new
--     maker pages (8 wrong in 320). The line errors were two suppliers'
--     regions, fixed across all their lines: Alepat Taylor's brands are
--     Australia-wide, and Pail & Cooper is a Victorian distributor (its
--     Queensland rows dropped, but for the one brand it carries there).
--
-- Matched by name; a second run changes nothing more.

CREATE TEMP TABLE maker_in (name text PRIMARY KEY, handle text NOT NULL, website text, country text, makes text[] NOT NULL);

-- A page per maker, unclaimed, public. A handle someone already uses, or a
-- maker that already has a page by this name, is left alone.
SELECT 'maker', m.handle, m.name, m.website, m.country, m.makes, true
  FROM maker_in m
 WHERE NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.handle = m.handle)
   AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.kind = 'maker' AND lower(p.display_name) = lower(m.name));

-- A maker page an earlier load made gains what this one says it makes.
UPDATE public.profiles p SET makes = ARRAY(SELECT DISTINCT unnest(p.makes || m.makes) ORDER BY 1)
  FROM maker_in m
 WHERE p.kind = 'maker' AND lower(p.display_name) = lower(m.name) AND NOT (m.makes <@ p.makes);

CREATE TEMP TABLE supplier_in (name text PRIMARY KEY, handle text NOT NULL, website text, supplies text[] NOT NULL, serves text[] NOT NULL);

-- A page per supplier, unclaimed, public, in Australia.
SELECT 'supplier', s.handle, s.name, s.website, 'AU', s.supplies, s.serves, true
  FROM supplier_in s
 WHERE NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.handle = s.handle)
   AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.kind = 'supplier' AND lower(p.display_name) = lower(s.name));

CREATE TEMP TABLE line_in (supplier text NOT NULL, maker text NOT NULL, region text NOT NULL, source_url text NOT NULL);

-- Whose brands each supplier carries, and where, with the page that says so.
-- A line whose supplier or maker has no page is skipped.
SELECT DISTINCT ON (s.id, m.id, l.region) s.id, m.id, l.region, l.source_url
  FROM line_in l
  JOIN public.profiles s ON s.kind = 'supplier' AND lower(s.display_name) = lower(l.supplier)
  JOIN public.profiles m ON m.kind = 'maker' AND lower(m.display_name) = lower(l.maker)
 ORDER BY s.id, m.id, l.region, m.created_at
ON CONFLICT ON CONSTRAINT "supplier_lines_one_per_region" DO NOTHING;

DROP TABLE maker_in, supplier_in, line_in;
